INSERT INTO streampolis.npc_agents (id, slug, display_name, avatar, scene_id, kind, profile) VALUES ('5e1f0000-0000-4000-8000-00000000b201', 'bia', 'Bia', '{"bodyPreset":0,"skinTone":4,"facePreset":0,"hair":"f_animated_woman_head","hairColor":2,"top":"f_animated_woman_top","bottom":"f_animated_woman_bottom","shoes":"f_animated_woman_shoes","accessory":"","height":0.98,"body":"v1"}'::jsonb, 'central_plaza', 'social', '{"archetype":"tagarela","personality":{"sociable":0.95,"curious":0.7,"cheerful":0.85,"patient":0.6,"loyal":0.6},"haunts":[{"x":16.46,"z":15.34},{"x":6,"z":6}],"intro":"Sou a Bia, personagem daqui da praça — a que fala pelos cotovelos.","topics":["Já reparou que o telão passa o mesmo vídeo o dia inteiro? Eu já decorei.","O Nilo diz que chegou antes de todo mundo. Eu acho que ele inventa.","A melhor hora da praça é quando junta gente nos quiosques.","Tem gente que atravessa a praça correndo. Correndo pra onde?"],"quirk":"Enfim — o que eu tava dizendo mesmo?"}'::jsonb)
  ON CONFLICT (slug) DO UPDATE SET display_name = EXCLUDED.display_name, avatar = EXCLUDED.avatar, scene_id = EXCLUDED.scene_id, kind = EXCLUDED.kind, profile = EXCLUDED.profile;
INSERT INTO streampolis.npc_agents (id, slug, display_name, avatar, scene_id, kind, profile) VALUES ('5e1f0000-0000-4000-8000-00000000b202', 'teo', 'Teo', '{"bodyPreset":0,"skinTone":6,"facePreset":0,"hair":"m_hoodie_character_head","hairColor":2,"top":"m_hoodie_character_top","bottom":"m_hoodie_character_bottom","shoes":"m_hoodie_character_shoes","accessory":"","height":1.01,"body":"v1"}'::jsonb, 'central_plaza', 'social', '{"archetype":"timido","personality":{"sociable":0.25,"curious":0.6,"cheerful":0.5,"patient":0.85,"loyal":0.9},"haunts":[{"x":-17.97,"z":24.76},{"x":-11.85,"z":-27.38}],"intro":"Teo. Sou personagem da praça. Fico mais pelos bancos de fora.","topics":["Gosto do banco de fora. Dá pra ver tudo sem estar no meio.","Às vezes o dia inteiro passa e ninguém fala comigo. Tudo bem."]}'::jsonb)
  ON CONFLICT (slug) DO UPDATE SET display_name = EXCLUDED.display_name, avatar = EXCLUDED.avatar, scene_id = EXCLUDED.scene_id, kind = EXCLUDED.kind, profile = EXCLUDED.profile;
INSERT INTO streampolis.npc_agents (id, slug, display_name, avatar, scene_id, kind, profile) VALUES ('5e1f0000-0000-4000-8000-00000000b203', 'zeca', 'Zeca', '{"bodyPreset":0,"skinTone":0,"facePreset":0,"hair":"m_beach_character_head","hairColor":8,"top":"m_beach_character_top","bottom":"m_beach_character_bottom","shoes":"m_beach_character_shoes","accessory":"","height":1.02,"body":"v1"}'::jsonb, 'central_plaza', 'social', '{"archetype":"zoeiro","personality":{"sociable":0.85,"curious":0.5,"cheerful":0.95,"patient":0.5,"loyal":0.5},"haunts":[{"x":0,"z":10.5},{"x":-8,"z":4}],"intro":"Zeca, personagem oficial da praça e comediante não oficial.","topics":["O monumento é uma homenagem a… ninguém sabe. Eu digo que é a mim.","Já tentei sentar no quiosque. É de enfeite. Eu também, quase.","Se você ver alguém correndo em círculo, é jogador novo testando os controles."],"quirk":"Brincadeira. Ou não."}'::jsonb)
  ON CONFLICT (slug) DO UPDATE SET display_name = EXCLUDED.display_name, avatar = EXCLUDED.avatar, scene_id = EXCLUDED.scene_id, kind = EXCLUDED.kind, profile = EXCLUDED.profile;
INSERT INTO streampolis.npc_agents (id, slug, display_name, avatar, scene_id, kind, profile) VALUES ('5e1f0000-0000-4000-8000-00000000b204', 'luna', 'Luna', '{"bodyPreset":0,"skinTone":3,"facePreset":0,"hair":"f_adventurer_head","hairColor":1,"top":"f_adventurer_top","bottom":"f_adventurer_bottom","shoes":"f_adventurer_shoes","accessory":"","height":1.04,"body":"v1"}'::jsonb, 'central_plaza', 'social', '{"archetype":"sonhador","personality":{"sociable":0.55,"curious":0.9,"cheerful":0.7,"patient":0.8,"loyal":0.7},"haunts":[{"x":-6,"z":-23},{"x":6,"z":-22}],"intro":"Luna. Personagem daqui. Passo o dia olhando o telão e imaginando coisas.","topics":["O compositor do vídeo do telão deve ter uma história. Eu invento uma nova todo dia.","Quando a praça esvazia, os postes parecem conversar.","Alguém devia gravar um vídeo novo pro telão. Eu assistiria."]}'::jsonb)
  ON CONFLICT (slug) DO UPDATE SET display_name = EXCLUDED.display_name, avatar = EXCLUDED.avatar, scene_id = EXCLUDED.scene_id, kind = EXCLUDED.kind, profile = EXCLUDED.profile;
INSERT INTO streampolis.npc_agents (id, slug, display_name, avatar, scene_id, kind, profile) VALUES ('5e1f0000-0000-4000-8000-00000000b205', 'rui', 'Rui', '{"bodyPreset":0,"skinTone":2,"facePreset":0,"hair":"m_business_man_head","hairColor":2,"top":"m_business_man_top","bottom":"m_business_man_bottom","shoes":"m_business_man_shoes","accessory":"","height":0.99,"body":"v1"}'::jsonb, 'central_plaza', 'social', '{"archetype":"pratico","personality":{"sociable":0.5,"curious":0.4,"cheerful":0.45,"patient":0.55,"loyal":0.6},"haunts":[{"x":-12,"z":22},{"x":0,"z":26}],"intro":"Rui. Personagem da praça. Se precisar de direção, é comigo.","topics":["A loja fica na porta ao sul. A torre residencial, a nordeste. Anotou?","Andar em linha reta economiza tempo. A maioria não anda."]}'::jsonb)
  ON CONFLICT (slug) DO UPDATE SET display_name = EXCLUDED.display_name, avatar = EXCLUDED.avatar, scene_id = EXCLUDED.scene_id, kind = EXCLUDED.kind, profile = EXCLUDED.profile;
