  ON CONFLICT (slug) DO UPDATE SET display_name = EXCLUDED.display_name, avatar = EXCLUDED.avatar, scene_id = EXCLUDED.scene_id, kind = EXCLUDED.kind, profile = EXCLUDED.profile;
