INSERT INTO streampolis.npc_agents (id, slug, display_name, avatar, scene_id, kind, profile) VALUES ('5e1f0000-0000-4000-8000-00000000b207', 'otto', 'Otto', '{"bodyPreset":0,"skinTone":2,"facePreset":0,"hair":"m_worker_head","hairColor":3,"top":"m_worker_top","bottom":"m_worker_bottom","shoes":"m_worker_shoes","accessory":"","height":1.02,"body":"v1"}'::jsonb, 'noir_district', 'social', '{"archetype":"rabugento","personality":{"sociable":0.35,"curious":0.3,"cheerful":0.2,"patient":0.3,"loyal":0.8},"haunts":[{"x":-47.5,"z":-5.5},{"x":-44,"z":5.5}],"intro":"Otto. Personagem deste bairro. Não, o bar não abre.","topics":["Essa chuva não para nunca. Nem eu.","Antigamente o bairro era mais escuro. Melhor.","Tem gente que vem aqui pra correr bico. Eu venho pra ficar parado."],"quirk":"Hm."}'::jsonb)
  ON CONFLICT (slug) DO UPDATE SET display_name = EXCLUDED.display_name, avatar = EXCLUDED.avatar, scene_id = EXCLUDED.scene_id, kind = EXCLUDED.kind, profile = EXCLUDED.profile;
INSERT INTO streampolis.npc_agents (id, slug, display_name, avatar, scene_id, kind, profile) VALUES ('5e1f0000-0000-4000-8000-00000000b208', 'selene', 'Selene', '{"bodyPreset":0,"skinTone":0,"facePreset":0,"hair":"f_suit_head","hairColor":8,"top":"f_suit_top","bottom":"f_suit_bottom","shoes":"f_suit_shoes","accessory":"","height":0.98,"body":"v1"}'::jsonb, 'noir_district', 'social', '{"archetype":"misterioso","personality":{"sociable":0.4,"curious":0.85,"cheerful":0.4,"patient":0.7,"loyal":0.5},"haunts":[{"x":-24,"z":-12},{"x":4,"z":-11}],"intro":"Pode me chamar de Selene. Personagem deste bairro. O resto é detalhe.","topics":["A passagem oeste leva à travessa. A travessa leva a lugar nenhum. Gosto dela.","O beco tem um tambor aceso. Ninguém sabe quem acende.","Nem toda porta fechada está fechada por dentro."]}'::jsonb)
