INSERT INTO streampolis.npc_agents (id, slug, display_name, avatar, scene_id, kind, profile) VALUES ('5e1f0000-0000-4000-8000-00000000b209', 'jorge', 'Jorge', '{"bodyPreset":0,"skinTone":2,"facePreset":0,"hair":"m_casual_character_head","hairColor":6,"top":"m_casual_character_top","bottom":"m_casual_character_bottom","shoes":"m_casual_character_shoes","accessory":"","height":1,"body":"v1"}'::jsonb, 'noir_district', 'social', '{"archetype":"malandro","personality":{"sociable":0.9,"curious":0.5,"cheerful":0.8,"patient":0.6,"loyal":0.55},"haunts":[{"x":16,"z":-4.2},{"x":26,"z":4.6}],"intro":"Jorge, personagem do bairro. Conheço todo mundo e devo pra ninguém.","topics":["Bico bom é o curto. O pagamento é o mesmo, a caminhada é menor.","O clube tá sempre aberto. É a única coisa que abre.","Se vir a Dalva, manda um abraço. Ela não retribui, mas manda."],"quirk":"Salve!"}'::jsonb)
